sys_script_fix.script:
function removeSoftwareModelInstallCondition() {
	var smGr = new GlideMultipleUpdate('cmdb_software_product_model');
	smGr.addNotNullQuery('database_option');
	smGr.addNotNullQuery('install_condition');
	smGr.setValue('install_condition', '');
	smGr.execute();
}

removeSoftwareModelInstallCondition();
